#!/usr/bin/env python3
"""Build a publication-safe technical learning record, offline without API calls."""
from html import escape
import json
from pathlib import Path
import zipfile
from build_learning_hub import CSS
from report_series import finish_page

ROOT=Path(__file__).resolve().parents[1]
FOLDER=ROOT/'stages/05-technical-discoverability'
SOURCES=[
 ('Google URL Inspection API','https://developers.google.com/webmaster-tools/v1/urlInspection.index/inspect','Queries the indexed version; it is not a live test or an indexing request.'),
 ('Google Sitemap fields','https://developers.google.com/webmaster-tools/v1/sitemaps','Submission, processing and download observations are separate fields.'),
 ('Bing GetUrlInfo','https://learn.microsoft.com/en-us/dotnet/api/microsoft.bing.webmaster.api.interfaces.iwebmasterapi.geturlinfo?view=bing-webmaster-dotnet','The returned URL fields do not supply an unambiguous membership verdict.'),
 ('Bing API fault codes','https://learn.microsoft.com/en-us/dotnet/api/microsoft.bing.webmaster.api.interfaces.apierrorcode?view=bing-webmaster-dotnet','ThrottleHost is code 5; the observed response used HTTP 400.'),
 ('Bing URL Inspection','https://blogs.bing.com/webmaster/2020/9/Introducing-the-Bing-Webmaster-Tools-URL-Inspection-Tool/','Index details and a live URL check answer different questions.'),
 ('IndexNow protocol','https://www.indexnow.org/documentation','A project-subfolder key requires an explicit keyLocation; a receipt does not establish crawling or indexing.'),
 ('OpenAI crawlers','https://developers.openai.com/api/docs/bots','A declared user agent is different from a request whose source identity can be checked.'),
 ('GitHub Pages API','https://docs.github.com/en/rest/pages','Pages management/build interfaces are not a per-request crawler log.'),
]
EXTRA='''
section{margin-top:38px;padding-top:26px;border-top:1px solid var(--line)}section:first-of-type{margin-top:28px}.table-wrap{max-width:100%;overflow-x:auto;margin:18px 0 22px}table{width:100%;border-collapse:collapse;font-size:14px;line-height:1.55;min-width:590px}th,td{text-align:left;vertical-align:top;padding:12px 14px;border-bottom:1px solid var(--line)}thead th{background:var(--soft);color:#274b56;font-weight:700}tbody th{font-weight:650}td small{display:block;margin-top:5px;color:var(--muted)}.step-list li{margin:10px 0}.source-list li{margin:14px 0}.section-links{display:flex;flex-wrap:wrap;gap:10px 22px;margin:22px 0}.dates{font-variant-numeric:tabular-nums}.report-version{max-width:76ch}code{font-size:.9em;background:#eef4f5;padding:2px 4px;border-radius:3px}.table-wrap:focus-visible{outline:3px solid var(--accent);outline-offset:3px}@media(max-width:650px){nav{padding:14px 20px}nav a,nav .experiment-series a{padding:4px 0}.nav-links,.lab-utility-links{display:flex;flex-wrap:wrap;gap:3px 16px}table{font-size:13px}th,td{padding:10px}section{margin-top:30px;padding-top:22px}}
'''

def note(text):return '<blockquote><p>'+text+'</p></blockquote>'
def table(headers,rows):
 return '<div class="table-wrap" tabindex="0" role="region" aria-label="'+escape(' / '.join(headers),quote=True)+'"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>'for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'if i==0 else'<td>')+str(v)+('</th>'if i==0 else'</td>')for i,v in enumerate(row))+'</tr>'for row in rows)+'</tbody></table></div>'

def followups(summary):
    rows=summary.get('followups',[])
    if not rows:return ''
    return '<section id="followups"><h2>Later verified observations</h2>'+note('These dated follow-ups extend the record. They do not overwrite the earlier snapshots or establish an AI recommendation effect.')+table(['Time (UTC)','Observation','Verified result','Boundary'],[[escape(str(row[key]))for key in ('checked_at','observation','verified','limit')]for row in rows])+'</section>'

def navigation(items):return '<div class="nav-links">'+''.join('<a href="#'+key+'">'+title+'</a>'for key,title in items)+'</div>'
def document(title,items,content,kind):
 doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+CSS+EXTRA+'</style></head><body><a class="skip" href="#main">Skip to the learning record</a><div class="layout"><nav aria-label="GEO Lab 05 contents"><strong>GEO Lab #05</strong>'+navigation(items)+'<div class="nav-group lab-utility-links"><a href="'+('technical-appendix.html'if kind=='reader'else'./')+'">'+('Methods and source notes'if kind=='reader'else'Return to learning report')+'</a><a href="data/summary.json">Public summary data</a><a href="public-data.zip">Download public summary</a></div></nav><main id="main"><h1>'+title+'</h1>'+content+'<p class="footer">Helen Bird · GEO Learning Log · <a href="https://github.com/helen-bird/geo-platform-observation">Repository</a></p></main></div></body></html>'
 return finish_page(doc,5,kind=kind)

def render(summary):
 g=summary['google'];b=summary['bing'];o=summary['openai_search'];i=summary['indexnow'];good=b['successful_batch'];bad=b['later_joint_attempt']
 intro='<p class="lead">What can a search-engine check actually tell me about whether people will discover my work through AI?</p><p class="author"><strong>Author:</strong> Helen Bird · <strong>First published:</strong> 2026-11-06 · <strong>Updated:</strong> 2026-11-06</p>'
 intro+=note('<strong>Technical learning record, not an AI-answer experiment.</strong> The observations below were collected on November 4–6, 2026. No new ChatGPT or Grok recommendations were measured. This page publishes reviewed aggregates; private raw engine/account evidence is excluded.')
 conclusions='''<section id="conclusions"><h2>What I learned</h2><ul><li><strong>A successful query can still leave indexing unknown.</strong> One Bing batch returned successful results for all 70 URLs, yet the returned fields did not establish that any page was indexed.</li><li><strong>Access, crawling, indexing and recommendation need separate evidence.</strong> Seventy successful requests using a declared OpenAI crawler user agent demonstrate simulated access, not a real OpenAI crawler visit.</li><li><strong>Submission and processing are different outcomes.</strong> Google accepted the Sitemap submission; its later processing flag was still pending. Bing separately reported a successful imported feed.</li><li><strong>Keep failures visible.</strong> A later joint run hit Bing throttling after 11 successful URL queries. The failed request and 58 skipped positions remain in the history; they were not converted into indexing results.</li></ul>'''+note('These are time-bounded observations, not a controlled GEO intervention. The successful ten-second batch and later five-second batch differed in time as well as spacing. They cannot prove that one request interval caused the different outcomes.')+'</section>'
 rows=[['Google indexing',f"{g['indexed']} indexed / {g['not_indexed']} not indexed, among {g['scope_urls']} important URLs",'Official indexed-version API results','A Google index result does not establish Bing or ChatGPT indexing.'],['Bing URL information',f"{good['queries_succeeded']}/{good['url_queries']} URL queries succeeded in one batch",f"{good['index_membership_unknown']} index-membership states remain UNKNOWN",'HTTP 200, IsPage and default dates are not membership verdicts.'],['OpenAI crawl eligibility',f"{o['configuration_allowed']} configuration-allowed / {o['declared_user_agent_fetch_succeeded']} simulated fetches succeeded",'Real crawler visits and OpenAI indexing: UNKNOWN','The requests were made by the monitoring environment, not verified OpenAI source IPs.'],['IndexNow',f"{i['post_count']} notification POSTs at the recorded snapshot; {i['scope_urls_before_publication']} unchanged URLs",'Key file publicly reachable; remote validation not yet observed','No unchanged URL was re-submitted just to manufacture a receipt.']]
 observations='<section id="observations"><h2>Four observations, four meanings</h2>'+note('Scope and time: Google checked 10 important editorial routes; Bing, OpenAI eligibility and the initial IndexNow ledger covered 70 canonical content URLs, including individual-answer archives. These are not interchangeable denominators. The new reader and methods page add two editorial URLs after those snapshots; they were not part of the earlier counts.')+table(['Dimension','Observed result','Interpretation','Boundary'],rows)+'<p>Google snapshot: <time class="dates">'+escape(g['checked_at'])+'</time>. Bing successful batch started: <time class="dates">'+escape(good['checked_at'])+'</time>. The <a href="technical-appendix.html#timeline">methods appendix</a> keeps the later failed run and separate source times visible.</p></section>'
 pipeline='''<section id="evidence"><h2>Ask what each signal proves</h2><ol class="step-list"><li><strong>Configuration and access:</strong> canonical URLs, indexability directives, effective robots rules and HTTP access establish current technical conditions.</li><li><strong>Discovery and crawling:</strong> an engine-associated crawl timestamp or verified request log can show that a system encountered a page. A missing timestamp leaves that evidence unknown.</li><li><strong>Indexing:</strong> use the engine's explicit indexed-version verdict when available. Do not infer membership from a successful information query.</li><li><strong>AI retrieval and recommendation:</strong> test user questions separately, with repeat runs and original answers. Search-engine indexing alone does not supply this evidence.</li></ol>'''+note('The original GitHub Pages URL does not currently expose a confirmed owner-accessible per-request crawler log. Repository Traffic is not a substitute for a Pages access log. Real OAI-SearchBot access therefore remains UNKNOWN.')+'</section>'
 implementation='''<section id="workflow"><h2>A small workflow I can keep using</h2><ul><li><strong>Save a baseline before making changes.</strong> Keep manual observations and official API responses separate; do not backfill later results into an earlier date.</li><li><strong>Reuse one canonical URL inventory.</strong> Record which routes belong in the Sitemap and which supplemental archives remain crawlable.</li><li><strong>Keep engines separate.</strong> Save Google indexing, Bing information queries and OpenAI eligibility in their own snapshots.</li><li><strong>Stop on throttling or access failures.</strong> Retain the first blocking response and every remaining unqueried URL as UNKNOWN with zero attempts.</li><li><strong>Preserve history privately.</strong> Raw responses and account evidence stay outside the public Pages repository. Publish only reviewed summaries.</li><li><strong>Notify only after evidence is durable.</strong> A completed, successful GitHub run and committed full snapshot precede the first complete-batch notification.</li></ul>'''+note('The recurring monitor is configured for Monday 10:17 Asia/Shanghai; GitHub may delay its start. Configuration and a manual workflow dispatch do not prove that the first scheduled occurrence has run. Ordinary Google indexing requests remain manual.')+'<p><a href="https://github.com/helen-bird/geo-platform-observation/blob/main/docs/multi-engine-discoverability.md">Read the implementation and safety boundaries</a>.</p></section>'
 failures='<section id="failures"><h2>What the failed run changed</h2>'+table(['Recorded batch','URL results','Spacing','What remains unknown'],[['Earlier Bing-only batch','70 succeeded; 0 failed; 0 skipped','10-second configuration; minimum observed response gap about 10.21 seconds','Indexing and valid page-crawl evidence were not established.'],['Later combined monitor','11 succeeded; 1 ThrottleHost fault; 58 skipped after the block','5-second configuration','No results are invented for skipped positions; future quota availability is unknown.']])+note('Bing returned ThrottleHost (official code 5) with HTTP 400. Treating only HTTP 429 as throttling would miss this case. The program now recognizes provider fault codes, stops the batch and records skipped positions. A successful earlier batch does not erase a later failure.')+'</section>'
 next_steps='''<section id="next"><h2>What I would reuse as an independent builder</h2><ul><li><strong>Measure one layer at a time.</strong> Name the evidence you want before choosing an API or dashboard.</li><li><strong>Use UNKNOWN as a real result.</strong> Missing or ambiguous fields should not become a negative indexing verdict.</li><li><strong>Publish useful changes, then notify.</strong> A genuine report or corrected learning resource can create an eligible IndexNow change; a test edit, date-only change or repeated old URL does not establish a useful intervention.</li><li><strong>Keep a change timeline.</strong> Technical fixes, Sitemap submission, manual indexing requests and later publication are separate events. Their effects cannot be pooled into one causal claim.</li></ul>'''+note('Still open in this snapshot: Google Sitemap processing, current Bing membership, real OpenAI crawler access, a real IndexNow receipt and a successful combined monitor run. New observations can close operational checks without proving recommendation lift.')+'<p class="section-links"><a href="technical-appendix.html">Methods, sources and publication scope</a><a href="public-data.zip">Download reviewed public summary</a></p></section>'
 return document('GEO Lab #05: Technical Discoverability', [('conclusions','What I learned'),('observations','Observed results'),('evidence','What each signal proves'),('workflow','Reusable workflow'),('failures','Failures retained'),('next','Next questions')],intro+conclusions+followups(summary)+observations+pipeline+implementation+failures+next_steps,'reader')

def appendix(summary):
 g=summary['google'];b=summary['bing'];o=summary['openai_search'];i=summary['indexnow'];good=b['successful_batch'];bad=b['later_joint_attempt']
 content='<p class="lead">Methods and source notes for the fifth learning record. This is a summary of technical observations, not an archive of new AI answers.</p>'+note('<strong>Publication boundary.</strong> The public JSON reproduces the visible aggregate tables. It is not a raw Search Console or Bing export. Private raw responses, screenshots, account/verification identifiers, secrets and private workflow links are not published.')
 content+='<section id="design"><h2>Design and units</h2><ul><li><strong>Google:</strong> 10 important editorial/navigation/appendix URLs, checked with the official indexed-version URL Inspection API.</li><li><strong>Bing:</strong> 70 canonical content URLs, plus read-only site and Sitemap queries. A successful batch therefore has 72 API reads, not 72 indexed pages.</li><li><strong>OpenAI eligibility:</strong> 70 public URLs checked for observable configuration/access conditions and fetched using a declared crawler user agent.</li><li><strong>IndexNow:</strong> 70 deployed content fingerprints in the initial ledger. Only a verified real content addition, material update or deletion is eligible for a notification.</li></ul>'+note('Lab #05 is not the postponed AI-search experiment. No ChatGPT/Grok prompt, recommendation rate, brand mention uplift or citation effect was measured here. The earlier AI-answer evidence library remains at 60 selected answers across Labs #01–#04.')+'</section>'
 content+='<section id="timeline"><h2>Separate observations in time</h2>'+table(['Observation','Source time (UTC)','Recorded result'],[['Google indexed-version snapshot',escape(g['checked_at']),'5 INDEXED; 5 NOT_INDEXED.'],['Bing successful information-query batch',escape(good['checked_at']),'70/70 URL queries succeeded; 70 index-membership and crawl-lifecycle states UNKNOWN.'],['Later combined monitor: Bing phase',escape(bad['checked_at']),'11 successes; 1 ThrottleHost fault; 58 unqueried quota-blocked positions.'],['OpenAI configuration and declared-UA simulation',escape(o['checked_at']),'70 configuration-allowed and 70 simulated fetch successes; real crawler/index UNKNOWN.'],['IndexNow ledger/key observation',escape(i['checked_at']),'70 unchanged URLs; key file matched; 0 POSTs.']])+note('Times describe their source observations, not this page publication. Collection windows, engine outcomes and later interpretation remain separate. Default or absent date values are not turned into crawl evidence.')+'</section>'
 content+='<section id="sitemaps"><h2>Sitemap submission is not indexing</h2>'+table(['Engine','Separate recorded status','Limit'],[['Google','One official submission accepted with HTTP 204 on November 4. Latest read: isPending=true; lastDownloaded absent.','No confirmed download/processing completion at this snapshot. Missing download time is not itself a diagnosed crawl failure.'],['Bing','Existing imported feed confirmed as registered / Success, reporting 10 URLs in the successful read.','A later quota stop skipped the feed read. It does not revoke the earlier Success observation or prove per-URL indexing.']])+note('The public Sitemap is generated from recorded canonical routes and real editorial revision dates. This edition adds the Lab #05 reader and methods page. Its new routes are not retroactively included in the earlier ten-URL feed observation or seventy-URL batch results.')+'</section>'
 content+=followups(summary)
 content+='''<section id="rules"><h2>Rules that protect the record</h2><ul><li>Retain original fields and immutable snapshots. Keep derived summaries separate from source observations.</li><li>Query success and HTTP status never override a missing indexed-version verdict.</li><li>Keep each planned URL, including failures and zero-attempt skipped positions.</li><li>Use a fixed property and approved read operations. Google readonly authorization and Bing's account-wide API key are different permission models; the program limits Bing calls to the approved site.</li><li>Keep credentials in protected storage and private encrypted workflow Secrets, never public content or state.</li><li>Preserve uncertain delivery state. A received IndexNow request or a confirmed notification is not a crawl/index confirmation.</li><li>Compare source times and execution environments. One local or manually dispatched success cannot prove every recurring scheduled run will pass.</li></ul></section>'''
 content+='<section id="sources"><h2>Official references</h2><ul class="source-list">'+''.join('<li><a href="'+escape(url,quote=True)+'">'+escape(title)+'</a><p>'+escape(explanation)+'</p></li>'for title,url,explanation in SOURCES)+'</ul></section>'
 content+='''<section id="data"><h2>Public data and reproduction</h2><p><a href="data/summary.json">Reviewed aggregate observations</a> · <a href="data/publication-notes.json">Publication scope</a> · <a href="public-data.zip">Download the public summary</a></p><p>Build this edition offline with <code>python3 scripts/build_stage5_report.py</code>; rebuild the full site with <code>python3 scripts/build_site.py --preserve-evidence</code>. These commands do not call search engines or submit URLs.</p><p>The public monitoring code can be adapted to another verified site using its owner's authorization. The private raw responses are not in the download, so the aggregate checks cannot independently audit every source field.</p></section>'''
 return document('GEO Lab #05: Methods and Source Notes',[('design','Design and units'),('timeline','Observation timeline'),('sitemaps','Sitemap status'),('rules','Recordkeeping rules'),('sources','Official references'),('data','Public summary data')],content,'appendix')

def main():
 summary=json.loads((FOLDER/'data/summary.json').read_text())
 assert summary['record_type']=='technical_learning_record'and summary['ai_answer_experiments_run']is False
 (FOLDER/'index.html').write_text(render(summary));(FOLDER/'technical-appendix.html').write_text(appendix(summary))
 with zipfile.ZipFile(FOLDER/'public-data.zip','w',zipfile.ZIP_DEFLATED)as archive:
  for path in sorted((FOLDER/'data').glob('*.json')):archive.write(path,path.relative_to(FOLDER))
 print(json.dumps({'stage':5,'record_type':'technical_learning_record','public_raw_engine_responses':False,'ai_answer_experiments':0,'model_calls':0,'pages':2}))
if __name__=='__main__':main()
